# Generated by FWShift: Windows Defender Firewall rules for one host, created with New-NetFirewallRule. Read the
# report first: what is not written is listed there.
#
#   powershell -ExecutionPolicy Bypass -File THIS_FILE -DryRun   shows what it would create (-WhatIf), creates nothing
#   powershell -ExecutionPolicy Bypass -File THIS_FILE           creates the rules (as administrator)
#
# -PolicyStore names another store than the local one (PersistentStore), such as a GPO: -PolicyStore 'example.com\GPO'.
# Every rule is created in the rule group FWShift; nothing is deleted and no profile setting is changed. A rule of
# that group, or of one of its names, stops the script before anything is created; a call Windows refuses stops it
# where it is. To take the rules away again: Remove-NetFirewallRule -Group 'FWShift'
#
# Windows evaluates these rules together with every other rule of the host: a block rule beats an allow rule, and
# what no rule matches gets the profile's default. Block rules are written without what the allow rules above them
# allowed in the source; see the report.
[CmdletBinding()]
param([switch]$DryRun, [string]$PolicyStore = 'PersistentStore')
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$Group = 'FWShift'
$NamePrefix = 'FWShift-'
# The profiles in which the policy denies outbound connections no rule allows: their default must be Block.
$OutboundBlock = @()
$Created = 0
function Add-Rule([hashtable]$Rule) {
    if ($DryRun) { New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore -WhatIf; return }
    $null = New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore
    $script:Created++
}
if (-not $DryRun) {
    $taken = @(Get-NetFirewallRule -PolicyStore $PolicyStore -ErrorAction SilentlyContinue |
        Where-Object { $_.Group -eq $Group -or $_.Name -like ($NamePrefix + '*') })
    if ($taken.Count -gt 0) {
        throw ('rules of the group ' + $Group + ' or named ' + $NamePrefix + '... exist in ' + $PolicyStore + ' already (' +
            $taken[0].Name + '); nothing was created')
    }
}
foreach ($fwProfile in @(Get-NetFirewallProfile -PolicyStore ActiveStore)) {
    $name = [string]$fwProfile.Name
    if ([string]$fwProfile.Enabled -eq 'False') { Write-Warning ('the firewall is off in the profile ' + $name + ': no rule applies there') }
    if ([string]$fwProfile.DefaultInboundAction -eq 'Allow') {
        Write-Warning ('the profile ' + $name + ' allows inbound connections no rule blocks; this policy needs Block ' +
            '(Set-NetFirewallProfile -Name ' + $name + ' -DefaultInboundAction Block)')
    }
    if ($OutboundBlock -contains $name -and [string]$fwProfile.DefaultOutboundAction -ne 'Block') {
        Write-Warning ('the profile ' + $name + ' allows outbound connections that this policy denies; to deny them ' +
            'set Set-NetFirewallProfile -Name ' + $name + ' -DefaultOutboundAction Block')
    }
}

Add-Rule @{ Name = 'FWShift-firewall_1-1'; DisplayName = 'firewall 1 (1)'; Description = 'FWShift: firewall 1'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('502'); LocalAddress = @('172.16.40.5'); RemoteAddress = @('192.168.127.10-192.168.127.20') }
Add-Rule @{ Name = 'FWShift-firewall_1-2'; DisplayName = 'firewall 1 (2)'; Description = 'FWShift: firewall 1'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('502'); LocalAddress = @('192.168.127.10-192.168.127.20'); RemoteAddress = @('172.16.40.5') }
Add-Rule @{ Name = 'FWShift-firewall_2-1'; DisplayName = 'firewall 2 (1)'; Description = 'FWShift: firewall 2'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('23'); LocalAddress = @('0.0.0.0-255.255.255.255') }
Add-Rule @{ Name = 'FWShift-firewall_2-2'; DisplayName = 'firewall 2 (2)'; Description = 'FWShift: firewall 2'; Direction = 'Outbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('23'); LocalAddress = @('0.0.0.0-255.255.255.255') }
Add-Rule @{ Name = 'FWShift-firewall_3-1'; DisplayName = 'firewall 3 (1)'; Description = 'FWShift: firewall 3'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('443'); LocalAddress = @('192.168.127.50'); RemoteAddress = @('198.51.100.0/24') }
Add-Rule @{ Name = 'FWShift-firewall_3-2'; DisplayName = 'firewall 3 (2)'; Description = 'FWShift: firewall 3'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('443'); LocalAddress = @('198.51.100.0/24'); RemoteAddress = @('192.168.127.50') }
Add-Rule @{ Name = 'FWShift-firewall_4-1'; DisplayName = 'firewall 4 (1)'; Description = 'FWShift: firewall 4'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; LocalPort = @('20000-20010'); RemotePort = @('1024-65535'); RemoteAddress = @('192.168.127.30') }
Add-Rule @{ Name = 'FWShift-firewall_4-2'; DisplayName = 'firewall 4 (2)'; Description = 'FWShift: firewall 4'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; LocalPort = @('1024-65535'); RemotePort = @('20000-20010'); LocalAddress = @('192.168.127.30') }
Add-Rule @{ Name = 'FWShift-firewall_5-1'; DisplayName = 'firewall 5 (1)'; Description = 'FWShift: firewall 5'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4' }
Add-Rule @{ Name = 'FWShift-firewall_5-2'; DisplayName = 'firewall 5 (2)'; Description = 'FWShift: firewall 5'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4' }
Add-Rule @{ Name = 'FWShift-firewall_7-1'; DisplayName = 'firewall 7 (1)'; Description = 'FWShift: firewall 7'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; LocalAddress = @('0.0.0.0-255.255.255.255') }
