Add-Rule @{ Name = 'FWShift-firewall_8-1'; DisplayName = 'firewall 8 (1)'; Description = 'FWShift: firewall 8'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('8080-8090'); LocalAddress = @('192.168.127.60-192.168.127.69') }
Add-Rule @{ Name = 'FWShift-firewall_8-2'; DisplayName = 'firewall 8 (2)'; Description = 'FWShift: firewall 8'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('8080-8090'); RemoteAddress = @('192.168.127.60-192.168.127.69') }
Add-Rule @{ Name = 'FWShift-firewall_9-1'; DisplayName = 'firewall 9 (1)'; Description = 'FWShift: firewall 9'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; RemoteAddress = @('192.168.127.200-192.168.127.250') }
Add-Rule @{ Name = 'FWShift-firewall_9-2'; DisplayName = 'firewall 9 (2)'; Description = 'FWShift: firewall 9'; Direction = 'Outbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; LocalAddress = @('192.168.127.200-192.168.127.250') }
Add-Rule @{ Name = 'FWShift-firewall_10-1'; DisplayName = 'firewall 10 (1)'; Description = 'FWShift: firewall 10'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('22'); LocalAddress = @('192.168.127.60') }
Add-Rule @{ Name = 'FWShift-firewall_10-2'; DisplayName = 'firewall 10 (2)'; Description = 'FWShift: firewall 10'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('22'); RemoteAddress = @('192.168.127.60') }
Add-Rule @{ Name = 'FWShift-_default_-1'; DisplayName = '(default) (1)'; Description = 'FWShift: (default)'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'True'; Profile = 'Any' }
Add-Rule @{ Name = 'FWShift-_default_-2'; DisplayName = '(default) (2)'; Description = 'FWShift: (default)'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'True'; Profile = 'Any' }

# Not written:
#   rule firewall 6: disabled in the source, not written

if (-not $DryRun) { Write-Host ('Done: ' + $Created + ' rules created in the group ' + $Group) }
